referenceSolutions.javascript:
export function wordDictionary(operations            )                   {
const words=new Set        (),out                 =[];for(const [op,s] of operations){if(op==="addWord"){words.add(s);out.push(null);}else out.push([...words].some(w=>w.length===s.length&&[...s].every((c,i)=>c==="."||c===w[i])));}return out;
}

